//! The Windows App SDK for a process that is not packaged: the bootstrap
//! that adds the framework package of the runtime to the package graph of
//! the process, so that WinUI and the other classes of the SDK can be
//! activated.
//!
//! The reference has no such code: a C# application of the SDK has it
//! generated by the build tasks of the SDK's package, which compile
//! `MddBootstrapAutoInitializer.cs` and `UndockedRegFreeWinRT-AutoInitializer.cs`
//! into it. A Rust application has no such tasks; it calls
//! [`WindowsAppSdk::initialize`] before anything of WinUI, as the generated
//! initializers do when the process starts (docs/porting/winui.md, section
//! 3.3).
//!
//! `Microsoft.WindowsAppRuntime.Bootstrap.dll` is loaded at run time: the
//! application ships it beside the executable (it is part of the package
//! `Microsoft.WindowsAppSDK` on nuget.org, under `runtimes/win-<arch>/native`),
//! and the runtime of the version asked for is installed on the machine
//! (`WindowsAppRuntimeInstall-<arch>.exe`).

/// What the bootstrap asks for: the version of the framework package and how
/// a failure is reported.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct WindowsAppSdkOptions {
    /// The major and the minor version of the release, as `0xMMMMNNNN`
    /// (`WINDOWSAPPSDK_RELEASE_MAJORMINOR`).
    pub major_minor_version: u32,
    /// The tag of a preview or an experimental release; empty for a stable
    /// one.
    pub version_tag: String,
    /// The lowest version of the runtime package (`PACKAGE_VERSION`); zero
    /// for any of the release.
    pub min_version: u64,
    /// `MddBootstrapInitializeOptions`. The initializer the SDK generates
    /// shows the system's dialog that offers the runtime when none is
    /// installed (`OnNoMatch_ShowUI`); the default here is none, so that a
    /// process without a person in front of it fails with the result code.
    pub options: i32,
    /// The bootstrap library: its name, which the system looks for beside
    /// the executable first, or a path.
    pub bootstrap_library: String,
}

impl WindowsAppSdkOptions {
    /// `MddBootstrapInitializeOptions_None`.
    pub const OPTIONS_NONE: i32 = 0;
    /// `MddBootstrapInitializeOptions_OnNoMatch_ShowUI`.
    pub const OPTIONS_ON_NO_MATCH_SHOW_UI: i32 = 0x0008;

    /// The release whose metadata the bindings of the crate are generated
    /// from (`interop/winui.idl`): 1.6, any runtime version of it.
    pub const RELEASE_MAJOR_MINOR: u32 = 0x0001_0006;
}

impl Default for WindowsAppSdkOptions {
    fn default() -> Self {
        WindowsAppSdkOptions {
            major_minor_version: Self::RELEASE_MAJOR_MINOR,
            version_tag: String::new(),
            min_version: 0,
            options: Self::OPTIONS_NONE,
            bootstrap_library: "Microsoft.WindowsAppRuntime.Bootstrap.dll".to_string(),
        }
    }
}

/// Parses `major.minor` (as `1.6`) into the form of
/// [`WindowsAppSdkOptions::major_minor_version`].
pub fn parse_major_minor(text: &str) -> Option<u32> {
    let (major, minor) = text.trim().split_once('.')?;
    let major: u16 = major.parse().ok()?;
    let minor: u16 = minor.parse().ok()?;
    Some((u32::from(major) << 16) | u32::from(minor))
}

#[cfg(windows)]
pub use imp::WindowsAppSdk;

#[cfg(windows)]
mod imp {
    use super::WindowsAppSdkOptions;
    use ferroui_microcom::HResult;
    use windows_sys::Win32::System::LibraryLoader::{GetProcAddress, LoadLibraryW};

    type MddBootstrapInitialize2 = unsafe extern "system" fn(u32, *const u16, u64, i32) -> i32;
    type MddBootstrapShutdown = unsafe extern "system" fn();
    type WindowsAppRuntimeEnsureIsLoaded = unsafe extern "system" fn() -> i32;

    fn wide(text: &str) -> Vec<u16> {
        text.encode_utf16().chain(Some(0)).collect()
    }

    /// The process is set up to use the runtime while this lives; dropping
    /// it calls `MddBootstrapShutdown`, as the end of the process does for
    /// the initializer the SDK generates.
    pub struct WindowsAppSdk {
        shutdown: MddBootstrapShutdown,
    }

    impl WindowsAppSdk {
        /// `MddBootstrapInitialize2` of the bootstrap library, then
        /// `WindowsAppRuntime_EnsureIsLoaded` of the runtime library, which
        /// lets the process activate the classes of the framework package
        /// (the two initializers the SDK generates for a C# application).
        pub fn initialize(options: &WindowsAppSdkOptions) -> Result<WindowsAppSdk, String> {
            let library = wide(&options.bootstrap_library);
            // SAFETY: a terminated name. The library stays loaded for the
            // process.
            let module = unsafe { LoadLibraryW(library.as_ptr()) };
            if module.is_null() {
                return Err(format!(
                    "{} could not be loaded (it is shipped beside the executable: the package Microsoft.WindowsAppSDK, runtimes/win-<arch>/native)",
                    options.bootstrap_library
                ));
            }
            // SAFETY: a loaded module and terminated names; the exports have
            // the signatures of MddBootstrap.h.
            let (initialize, shutdown) = unsafe {
                let initialize = GetProcAddress(module, c"MddBootstrapInitialize2".as_ptr().cast())
                    .ok_or("the bootstrap library has no MddBootstrapInitialize2")?;
                let shutdown = GetProcAddress(module, c"MddBootstrapShutdown".as_ptr().cast())
                    .ok_or("the bootstrap library has no MddBootstrapShutdown")?;
                (
                    std::mem::transmute::<unsafe extern "system" fn() -> isize, MddBootstrapInitialize2>(initialize),
                    std::mem::transmute::<unsafe extern "system" fn() -> isize, MddBootstrapShutdown>(shutdown),
                )
            };

            let tag = wide(&options.version_tag);
            // SAFETY: plain values and a terminated tag that lives through
            // the call.
            let hr = unsafe { initialize(options.major_minor_version, tag.as_ptr(), options.min_version, options.options) };
            if hr < 0 {
                return Err(format!(
                    "MddBootstrapInitialize2 failed with {} for release {}.{} (is the Windows App Runtime of that release installed?)",
                    HResult(hr as u32),
                    options.major_minor_version >> 16,
                    options.major_minor_version & 0xFFFF
                ));
            }

            // UndockedRegFreeWinRT: load the runtime library of the framework
            // package, which makes its classes activatable for a process
            // without a package of its own.
            let runtime = wide("Microsoft.WindowsAppRuntime.dll");
            // SAFETY: a terminated name; the framework package is in the
            // package graph of the process now.
            let runtime_module = unsafe { LoadLibraryW(runtime.as_ptr()) };
            if runtime_module.is_null() {
                // SAFETY: the bootstrap succeeded above.
                unsafe { shutdown() };
                return Err("Microsoft.WindowsAppRuntime.dll could not be loaded from the framework package".to_string());
            }
            // SAFETY: a loaded module and a terminated name.
            if let Some(ensure) = unsafe { GetProcAddress(runtime_module, c"WindowsAppRuntime_EnsureIsLoaded".as_ptr().cast()) } {
                // SAFETY: the export takes nothing and returns a result code.
                let ensure = unsafe { std::mem::transmute::<unsafe extern "system" fn() -> isize, WindowsAppRuntimeEnsureIsLoaded>(ensure) };
                // SAFETY: as above.
                let hr = unsafe { ensure() };
                if hr < 0 {
                    // SAFETY: the bootstrap succeeded above.
                    unsafe { shutdown() };
                    return Err(format!("WindowsAppRuntime_EnsureIsLoaded failed with {}", HResult(hr as u32)));
                }
            }

            Ok(WindowsAppSdk { shutdown })
        }
    }

    impl Drop for WindowsAppSdk {
        fn drop(&mut self) {
            // SAFETY: the bootstrap of this value succeeded.
            unsafe { (self.shutdown)() };
        }
    }
}

#[cfg(test)]
mod tests {
    // Not from upstream: the reference has no such code.
    use super::*;

    #[test]
    fn the_release_is_major_and_minor() {
        assert_eq!(Some(0x0001_0006), parse_major_minor("1.6"));
        assert_eq!(Some(0x0001_0008), parse_major_minor(" 1.8 "));
        assert_eq!(None, parse_major_minor("1"));
        assert_eq!(None, parse_major_minor("one.six"));
        assert_eq!(WindowsAppSdkOptions::RELEASE_MAJOR_MINOR, WindowsAppSdkOptions::default().major_minor_version);
    }
}
